import static thaumcraft.test.ThaumaturgyProbe.*;
@Mod.EventBusSubscriber(modid=Thaumcraft.MODID)
public final class TaskClient {
 static final BlockPos Q=new BlockPos(440,205,8);static int ticks,stage;static long due;static WorkerGolem g,other;static SealEntity s,provider;static ChestBlockEntity chest;static final List<net.minecraft.world.entity.animal.cow.Cow> adults=new ArrayList<>();static net.minecraft.world.entity.animal.cow.Cow baby;static net.minecraft.world.entity.animal.wolf.Wolf wolf;static final List<BlockPos> logs=new ArrayList<>();
 static WorkerGolem spawn(ServerPlayer p,GolemDesign design,BlockPos q){return LogisticsClient.spawn(p,design,q);}
 static void reset(ServerPlayer p){var l=p.level();for(int x=26;x<=29;x++)for(int z=-1;z<=1;z++)l.setChunkForced(x,z,true);for(var e:l.getEntitiesOfClass(LivingEntity.class,new AABB(Q).inflate(45)))if(!(e instanceof net.minecraft.world.entity.player.Player))e.discard();for(var e:l.getEntitiesOfClass(ItemEntity.class,new AABB(Q).inflate(45)))e.discard();for(var q:BlockPos.betweenClosed(Q.offset(-12,0,-10),Q.offset(24,9,10)))l.setBlockAndUpdate(q,Blocks.AIR.defaultBlockState());for(var q:BlockPos.betweenClosed(Q.offset(-12,-1,-10),Q.offset(24,-1,10)))l.setBlockAndUpdate(q,Blocks.STONE.defaultBlockState());}
 static void snapshot(ServerPlayer p){var out=TagValueOutput.createWithContext(ProblemReporter.DISCARDING,p.registryAccess());g.saveWithoutId(out);var copy=new WorkerGolem(GolemContent.GOLEM.get(),p.level());copy.load(TagValueInput.create(ProblemReporter.DISCARDING,p.registryAccess(),out.buildResult()));check(s.getBlockPos().equals(copy.delivery())&&copy.cargo.getItem(0).getCount()==1,"Use delivery lost route/cargo");g.discard();copy.setUUID(UUID.randomUUID());g=copy;check(p.level().addFreshEntity(g),"Cannot restore Use worker");}
 static long alive(){return adults.stream().filter(LivingEntity::isAlive).count();}
 @SubscribeEvent public static void tick(TickEvent.ServerTickEvent.Post e){if(!System.getProperty("thaumcraft.thaumaturgyProbe","").equals("tasks-client")||e.server().isDedicatedServer()||e.server().getPlayerList().getPlayers().isEmpty()||++ticks<80)return;var p=e.server().getPlayerList().getPlayers().getFirst();var l=p.level();long now=l.getGameTime();
  if(stage==0){var recipe=l.recipeAccess().getRecipes().stream().map(h->h.value()).filter(r->r instanceof thaumcraft.infusion.InfusionRecipe inf&&inf.research().equals("SEALBUTCHER")).map(r->(thaumcraft.infusion.InfusionRecipe)r).findFirst().orElseThrow();var recipeInput=new thaumcraft.infusion.InfusionInput(item("seal_guard"),List.of(new ItemStack(Items.LEATHER),new ItemStack(net.minecraft.core.registries.BuiltInRegistries.ITEM.getValue(net.minecraft.resources.Identifier.withDefaultNamespace("red_wool"))),new ItemStack(Items.RABBIT_HIDE),new ItemStack(Items.PORKCHOP),new ItemStack(Items.MUTTON),new ItemStack(Items.BEEF)));check(recipe.matches(recipeInput,l)&&recipe.assemble(recipeInput).is(GolemContent.SEALS.get(SealKind.BUTCHER).get().asItem()),"Butcher original infusion recipe/wool tag failed");knowledge(p);p.setGameMode(GameType.SURVIVAL);reset(p);p.teleportTo(l,Q.getX()+.5,Q.getY(),Q.getZ()-5.5,Set.of(),0,0,true);s=GolemProbe.seal(p,SealKind.USE,Q.east(7));l.setBlockAndUpdate(s.getBlockPos(),s.getBlockState().setValue(SealBlock.FACING,Direction.WEST));l.setBlockAndUpdate(s.support(),Blocks.STONE.defaultBlockState());s.useAir=true;s.useProvision=true;s.sample(0,new ItemStack(Items.DIRT));provider=GolemClient.chestSeal(p,SealKind.PROVIDER,Q.west(6));chest=(ChestBlockEntity)l.getBlockEntity(provider.support());chest.clearContent();chest.setItem(0,new ItemStack(Items.DIRT,5));provider.channel=1;stage=20;due=now+60;return;}
  if(stage==20&&now>=due){for(var old:l.getEntitiesOfClass(WorkerGolem.class,new AABB(Q).inflate(35)))old.discard();g=spawn(p,new GolemDesign(3,1,1,3),Q.west(2));stage=1;due=now+50;return;}
  if(stage==1&&now>=due){check(chest.getItem(0).getCount()==5&&g.cargo.isEmpty()&&l.isEmptyBlock(s.useTarget()),"Use fetched from wrong channel");provider.channel=0;l.setBlockAndUpdate(s.getBlockPos().south(),Blocks.REDSTONE_BLOCK.defaultBlockState());stage=2;due=now+50;return;}
  if(stage==2&&now>=due){check(chest.getItem(0).getCount()==5&&g.cargo.isEmpty(),"Powered Use requested supplies");l.removeBlock(s.getBlockPos().south(),false);stage=3;due=now+400;return;}
  if(stage==3){check(now<due,"Use provider leg timeout "+g.position());if(g.delivery()==null)return;check(chest.getItem(0).getCount()==4&&g.cargo.getItem(0).is(Items.DIRT)&&g.cargo.getItem(0).getCount()==1,"Use fetched more than one physical item");snapshot(p);l.setBlockAndUpdate(s.getBlockPos().south(),Blocks.REDSTONE_BLOCK.defaultBlockState());stage=4;due=now+40;return;}
  if(stage==4&&now>=due){check(l.isEmptyBlock(s.useTarget())&&g.cargo.getItem(0).getCount()==1,"Paused Use lost cargo or acted");l.removeBlock(s.getBlockPos().south(),false);stage=5;due=now+400;return;}
  if(stage==5){check(now<due,"Use delivery/action timeout "+g.position()+" cargo="+g.cargo.getItem(0)+" stand="+GolemInteraction.stand(s,g)+" box="+g.getBoundingBox()+" navDone="+g.getNavigation().isDone());if(!l.getBlockState(s.useTarget()).is(Blocks.DIRT))return;check(chest.getItem(0).getCount()==4&&g.cargo.isEmpty(),"Use placement duplicated or over-fetched");s.useAir=false;s.useProvision=false;s.useEmpty=true;l.setBlockAndUpdate(s.support(),Blocks.LEVER.defaultBlockState());stage=6;due=now+240;Thaumcraft.LOGGER.info("TASK_USE_SUPPLY_OK: actual two-leg request, channel/redstone, saved route and exactly one physical placement");return;}
  if(stage==6){check(now<due,"Empty-hand Use lever timeout");if(!l.getBlockState(s.support()).getValue(BlockStateProperties.POWERED))return;GolemClient.remove(s);GolemClient.remove(provider);g.discard();s=GolemProbe.seal(p,SealKind.LUMBER,Q.east().south(2));s.radius=6;for(int i=0;i<6;i++)logs.add(Q.east(4).above(i));logs.add(Q.east(5).above(4));logs.add(Q.east(6).above(5));for(var q:logs)l.setBlockAndUpdate(q,Blocks.OAK_LOG.defaultBlockState());l.setBlockAndUpdate(Q.east(15),Blocks.OAK_LOG.defaultBlockState());TaskProbe.denyBreak=true;g=spawn(p,new GolemDesign(1,1,3,0),Q.east(2));stage=7;due=now+50;Thaumcraft.LOGGER.info("TASK_USE_CLICK_OK: native empty-hand block interaction");return;}
  if(stage==7&&now>=due){check(logs.stream().allMatch(q->l.getBlockState(q).is(Blocks.OAK_LOG))&&g.cargo.isEmpty(),"Lumber bypassed Forge denial");TaskProbe.denyBreak=false;stage=8;due=now+600;return;}
  if(stage==8){check(now<due,"Lumber timeout "+g.position()+" logs="+logs.stream().filter(q->!l.isEmptyBlock(q)).toList());if(logs.stream().anyMatch(q->!l.isEmptyBlock(q)))return;check(g.cargo.getItem(0).is(Items.OAK_LOG)&&g.cargo.getItem(0).getCount()==8&&l.getBlockState(Q.east(15)).is(Blocks.OAK_LOG),"Lumber lost logs or cut outside bounds");GolemClient.remove(s);g.dropCargo(l);g.discard();s=GolemProbe.seal(p,SealKind.BUTCHER,Q.east(2).south(2));s.radius=6;for(int i=0;i<4;i++)adults.add(TaskProbe.cow(p,Q.east(4+i).south(),false));baby=TaskProbe.cow(p,Q.east(4).north(2),true);wolf=new net.minecraft.world.entity.animal.wolf.Wolf(net.minecraft.world.entity.EntityTypes.WOLF,l);wolf.setPos(Vec3.atBottomCenterOf(Q.east(3).north(2)));wolf.setNoAi(true);wolf.tame(p);l.addFreshEntity(wolf);g=spawn(p,new GolemDesign(1,1,0,2),Q.east());other=spawn(p,new GolemDesign(1,1,0,2),Q.east().south(2));check(g!=other,"Butcher fixture aliases workers");stage=9;due=now+800;Thaumcraft.LOGGER.info("TASK_LUMBER_OK: walking, denied cuts, eight connected/branch logs, real loot and out-of-area sentinel");return;}
  if(stage==9){check(now<due,"Butcher timeout, adults="+alive());check(alive()>=2&&baby.isAlive()&&wolf.isAlive(),"Butcher killed protected population");if(alive()!=2)return;stage=10;due=now+100;return;}
  if(stage==10&&now>=due){check(alive()==2&&baby.getHealth()==baby.getMaxHealth()&&wolf.getHealth()==wolf.getMaxHealth(),"Butcher hit breeding pair, baby or tame pet");GolemClient.remove(s);g.discard();other.discard();for(var a:adults)if(a.isAlive())a.discard();baby.discard();wolf.discard();s=GolemProbe.seal(p,SealKind.USE,Q.north(3));s.useProvision=true;s.sample(0,new ItemStack(Items.DIRT));p.teleportTo(l,Q.getX()+.5,Q.getY(),Q.getZ()-5.5,Set.of(),0,0,true);p.openMenu(s);stage=11;Thaumcraft.LOGGER.info("TASK_CLIENT_OK: Use/provision persistence, native clicks, bounded lumber and two butchers preserving adults/baby/tame pet");}
 }
}
